import{_ as i,o,c as t,a5 as c}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"G6 — AI Features (mobile)","description":"","frontmatter":{},"headers":[],"relativePath":"mobile/features/g6-ai-features/spec.md","filePath":"mobile/features/g6-ai-features/spec.md"}'),a={name:"mobile/features/g6-ai-features/spec.md"};function n(d,e,r,l,h,s){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="g6-—-ai-features-mobile" tabindex="-1">G6 — AI Features (mobile) <a class="header-anchor" href="#g6-—-ai-features-mobile" aria-label="Permalink to &quot;G6 — AI Features (mobile)&quot;">​</a></h1><p>&gt; Trạng thái: DRAFT — spec, không có code. &gt; Tham chiếu: <a href="./../mobile-app-plan.html">mobile-app-plan.md</a> §3 dòng G6, <a href="./../../ba/06-ai-features.html">docs/ba/06-ai-features.md</a>, <a href="./../../ba/use-cases/05-ai-features.html">docs/ba/use-cases/05-ai-features.md</a>.</p><h2 id="_1-muc-tieu-pham-vi" tabindex="-1">1. Mục tiêu &amp; phạm vi <a class="header-anchor" href="#_1-muc-tieu-pham-vi" aria-label="Permalink to &quot;1. Mục tiêu &amp; phạm vi&quot;">​</a></h2><p>Đưa 3 luồng AI generate chính của web (Caption, Image, Video) + credit balance/history lên mobile, theo đúng pattern <strong>generate-only, async job, charge-upfront/refund-on-fail</strong> đã có sẵn ở <code>AiVideoService</code>/<code>AiCaptionService</code>/<code>AiCreditService</code> (brandhub-business-service). Không build lại business logic — mobile chỉ là client mới gọi các endpoint đã có.</p><p>Trong phạm vi G6:</p><ul><li>Generate Video (Veo, prompt-based) — <code>AiVideoService</code>.</li><li>Generate Caption (3 variant/lần, refine, adapt sang platform khác) — <code>AiCaptionService</code>.</li><li>Generate Image (commercial image, ambassador làm input) — qua <code>AiGenerationController</code> pass-through, KHÔNG có service Java riêng kiểu <code>AiImageService</code>.</li><li>Xem AI credit balance (agency-level + creator limit nếu có) — <code>AiCreditService</code>.</li><li>Xem lịch sử job (video: <code>recent()</code>; caption: lịch sử generation theo <code>ai_caption_generations</code>, chưa có endpoint list riêng — xem mục 8).</li></ul><p>Ngoài phạm vi: xem <a href="./../../ba/07-publishing-social-collaborator.html">07-publishing-social-collaborator.md</a> và mục 7 dưới.</p><h2 id="_2-fr-tham-chieu" tabindex="-1">2. FR tham chiếu <a class="header-anchor" href="#_2-fr-tham-chieu" aria-label="Permalink to &quot;2. FR tham chiếu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>FR</th><th>Tên</th><th>Dùng ở G6?</th></tr></thead><tbody><tr><td>3.7.2</td><td>Generate Caption</td><td>Có</td></tr><tr><td>3.7.3</td><td>Generate Ambassador</td><td>Input phụ cho Image/Video, không phải màn hình riêng ở G6 MVP (xem mục 8)</td></tr><tr><td>3.7.4</td><td>View Image Style Template</td><td>Có (style picker)</td></tr><tr><td>3.7.5</td><td>Generate Image</td><td>Có</td></tr><tr><td>3.7.6</td><td>View Video Style Template</td><td>Có (<code>videos.styles()</code>)</td></tr><tr><td>3.7.7</td><td>Generate Video</td><td>Có</td></tr><tr><td>3.7.8</td><td>Export File</td><td>Có (save/share từ Result Preview)</td></tr><tr><td>3.7.1, 3.7.10</td><td>Trending topics/hashtag</td><td>Ngoài phạm vi G6 (có <code>trendFit()</code> dùng được cho caption context nhưng không làm màn hình riêng)</td></tr><tr><td>3.7.9</td><td>Crawl Schedule Config</td><td>Ngoài phạm vi — ADMIN, không áp dụng mobile Creator/Manager</td></tr><tr><td>3.7.11, 3.7.12</td><td>Livestream Script, Recommend Collaborator</td><td>Ngoài phạm vi G6</td></tr></tbody></table><h2 id="_3-api-can-dung" tabindex="-1">3. API cần dùng <a class="header-anchor" href="#_3-api-can-dung" aria-label="Permalink to &quot;3. API cần dùng&quot;">​</a></h2><h3 id="_3-1-video-workspace-scoped-charge-credit-qua-aicreditservice" tabindex="-1">3.1 Video (workspace-scoped, charge credit qua <code>AiCreditService</code>) <a class="header-anchor" href="#_3-1-video-workspace-scoped-charge-credit-qua-aicreditservice" aria-label="Permalink to &quot;3.1 Video (workspace-scoped, charge credit qua `AiCreditService`)&quot;">​</a></h3><p>Base: <code>/api/v1/workspaces/{workspaceId}/ai</code> (<code>AiVideoController</code>)</p><ul><li><code>GET /video-styles</code> → trả JSON style template list (proxy <code>ai.get(&quot;/api/v1/ai/video/styles&quot;)</code>).</li><li><code>POST /videos</code> → 202 Accepted. Body = <code>AiVideoService.Request { prompt (10-1000 ký tự), styleKey?, ambassadorId?, aspectRatio: &quot;16:9&quot;|&quot;9:16&quot; }</code>. Response = <code>Started { job, creditsUsed, creditsRemaining }</code>, <code>job.status</code> ban đầu <code>PENDING</code>.</li><li><code>GET /videos/{jobId}</code> → <code>Job { jobId, status, prompt, styleKey, ambassadorId, aspectRatio, videoUrl, s3Key, errorCode, refunded, createdAt, finishedAt }</code>. Nếu job đang <code>PENDING</code>/<code>PROCESSING</code>, server tự refresh từ AI service trước khi trả — mobile chỉ cần poll endpoint này, không cần gọi AI service trực tiếp.</li><li><code>GET /videos</code> → tối đa 12 job gần nhất của workspace (<code>recent()</code>), dùng cho Job History.</li></ul><h3 id="_3-2-caption-workspace-scoped-charge-credit" tabindex="-1">3.2 Caption (workspace-scoped, charge credit) <a class="header-anchor" href="#_3-2-caption-workspace-scoped-charge-credit" aria-label="Permalink to &quot;3.2 Caption (workspace-scoped, charge credit)&quot;">​</a></h3><p>Base: <code>/api/v1/workspaces/{workspaceId}/ai</code> (<code>AiCaptionController</code>)</p><ul><li><code>POST /captions</code> → đồng bộ (không async/job), trả ngay <code>Result { generationId, captions[3 variant], context, creditsUsed, creditsRemaining }</code>. Body = <code>Request { topic (10-1000), tone?, platform?, length?, language?, goal?, trend?, taskId?, trendId?, techniques? }</code>.</li><li><code>POST /captions/refine</code> → <code>DraftResult</code> (1 draft), body <code>RefineRequest { caption, instruction, feedback?, platform?, language?, topic? }</code>.</li><li><code>POST /captions/adapt</code> → <code>DraftResult</code> (nhiều draft, 1/platform), body <code>AdaptRequest { caption, platforms[], language?, topic? }</code>.</li><li><code>POST /captions/{generationId}/choice</code> → ghi lại variant Creator chọn, body <code>Choice { type, action: INSERT|REPLACE, finalText? }</code>. Không bắt buộc cho MVP nhưng nên gọi để dữ liệu history/few-shot đúng.</li><li><code>GET /trend-fit</code> → không charge credit, dùng optionally làm gợi ý trend khi soạn caption.</li></ul><h3 id="_3-3-image-khong-qua-aicreditservice-o-tang-java-—-khac-pattern-video-caption" tabindex="-1">3.3 Image (KHÔNG qua AiCreditService ở tầng Java — khác pattern video/caption) <a class="header-anchor" href="#_3-3-image-khong-qua-aicreditservice-o-tang-java-—-khac-pattern-video-caption" aria-label="Permalink to &quot;3.3 Image (KHÔNG qua AiCreditService ở tầng Java — khác pattern video/caption)&quot;">​</a></h3><p>Base: <code>/api/v1/ai</code> (<code>AiGenerationController</code>, pass-through tới <code>brandhub-ai-service</code>, thêm <code>client_id</code>/<code>workspace_id</code> vào body)</p><ul><li><code>POST /ambassadors/presets</code> (GET) và <code>POST /ambassadors/generate</code>, <code>POST /ambassadors/character-sheet</code> — tạo/làm mới Ambassador, dùng làm input cho Image/Video khi brand chưa có model thật (FR 3.7.3).</li><li><code>POST /image/commercial/generate</code> → proxy tới ai-service <code>/api/v2/ai/image/commercial/generate</code>. Request/response là <code>JsonNode</code> tự do (không có DTO Java riêng) — mobile cần lấy shape thật từ <code>brandhub-ai-service</code> (module <code>app/services/image/</code> — <code>prompt_synthesizer.py</code>, <code>style_presets.py</code>) hoặc từ web frontend trước khi code thật.</li><li><strong>Điểm cần lưu ý quan trọng:</strong> endpoint <code>/api/v1/ai/image/commercial/generate</code> KHÔNG đi qua <code>AiCreditService.ensureAvailable/charge</code> ở phía <code>AiGenerationController</code> — khác hẳn pattern video/caption. Nghĩa là hiện tại generate Image không tự động trừ credit ở tầng business-service (có thể trừ credit được xử lý bên <code>brandhub-ai-service</code> Python, hoặc đây là một gap/TODO của hệ thống). <strong>Cần xác nhận với team BE trước khi mobile hiển thị &quot;credit sẽ bị trừ&quot; cho luồng Image</strong> — xem mục 8 (câu hỏi mở).</li><li>Image generation ở <code>AiGenerationController</code> là <strong>đồng bộ</strong> (không có job/status polling riêng kiểu video) theo code hiện tại — không có <code>GET /image/{jobId}/status</code>. Nếu ai-service xử lý lâu, mobile sẽ phải chịu timeout HTTP đồng bộ thay vì poll — cần xác nhận thời gian xử lý thật của ai-service trước khi chốt UX (progress bar giả định vs spinner chờ).</li></ul><h3 id="_3-4-credit-balance" tabindex="-1">3.4 Credit balance <a class="header-anchor" href="#_3-4-credit-balance" aria-label="Permalink to &quot;3.4 Credit balance&quot;">​</a></h3><ul><li><code>GET /api/v1/workspaces/{workspaceId}/ai/credits</code> (đặt trong <code>AiCaptionController</code> nhưng dùng chung cho mọi feature AI) → <code>AiCreditService.Balance { agencyId, allowance, used, creatorLimit, creatorUsed, remaining }</code>. <code>remaining</code> = agency remainder, capped bởi creator limit nếu Owner có đặt. Gọi lại ngay sau mỗi generate video/caption để cập nhật UI (xem mục 5).</li></ul><h3 id="_3-5-polling-pattern-video-—-async" tabindex="-1">3.5 Polling pattern (video — async) <a class="header-anchor" href="#_3-5-polling-pattern-video-—-async" aria-label="Permalink to &quot;3.5 Polling pattern (video — async)&quot;">​</a></h3><ul><li>Sau <code>POST /videos</code>, mobile poll <code>GET /videos/{jobId}</code> theo <code>refetchInterval</code> (gợi ý 3-5s) <strong>chỉ khi</strong> <code>status</code> còn <code>PENDING</code>/<code>PROCESSING</code>; dừng polling khi <code>COMPLETED</code>/<code>FAILED</code>.</li><li>Server có sweep job riêng (<code>AiVideoService.sweep()</code>, chạy mỗi 60s mặc định qua <code>@Scheduled</code>) tự fail + refund job quá <code>timeoutSeconds</code> (mặc định 600s) dù không ai poll — mobile không cần tự làm timeout logic, chỉ cần tiếp tục poll hoặc tắt app rồi mở lại gọi <code>GET /videos/{jobId}</code> để lấy trạng thái mới nhất.</li><li>Push-notification-khi-job-xong: hiện <strong>chưa có</strong> cơ chế server push (không thấy FCM/APNs trigger trong <code>AiVideoService</code>). Đây là câu hỏi mở — xem mục 8.</li></ul><h2 id="_4-luong-man-hinh" tabindex="-1">4. Luồng màn hình <a class="header-anchor" href="#_4-luong-man-hinh" aria-label="Permalink to &quot;4. Luồng màn hình&quot;">​</a></h2><ol><li><strong>AI Hub</strong> — 3 card: Generate Video / Generate Image / Generate Caption, + khối hiển thị Credit balance (remaining/allowance) luôn hiện ở đầu màn hình.</li><li><strong>Prompt/Form screen</strong> (theo loại): <ul><li>Video: style picker (từ <code>GET /video-styles</code>) → prompt textarea (10-1000 ký tự) → chọn ambassador (optional, danh sách từ <code>/ambassadors/presets</code> nếu brand không có model thật) → aspect ratio 16:9/9:16 → nút Generate.</li><li>Caption: topic textarea, tone/platform/length/language/goal picker, optional trend/task link.</li><li>Image: style template picker (3.7.4) → form input + chọn ambassador + chọn material liên quan (từ Material Repository, liên kết G2) → nút Generate.</li></ul></li><li><strong>Generating state</strong>: <ul><li>Video: hiện &quot;Đã trừ N credit — đang xử lý&quot; ngay sau response 202 (credit đã charge ngay khi job được tạo, KHÔNG chờ xong mới trừ) + progress indicator (không có % thật, chỉ trạng thái PENDING→PROCESSING) trong lúc poll <code>GET /videos/{jobId}</code>.</li><li>Caption: đồng bộ, hiện spinner ngắn (gọi 1 lần, có kết quả ngay, không polling).</li><li>Image: đồng bộ (theo code hiện tại), hiện spinner chờ response — cảnh báo nếu lâu vì không có job/progress API.</li></ul></li><li><strong>Result Preview</strong>: <ul><li>Video: hiển thị <code>videoUrl</code> khi <code>status=COMPLETED</code>; nếu <code>status=FAILED</code> hiện lý do (<code>errorCode</code>) + thông báo credit đã hoàn (<code>refunded=true</code>).</li><li>Caption: hiện 3 variant, mỗi variant kèm <code>signals</code> (emotion/trend_used/unverified_claims), <code>compliance</code> check — cho phép chọn 1 variant (gọi <code>/choice</code>) hoặc Refine/Adapt tiếp.</li><li>Image: hiện ảnh generate xong.</li></ul></li><li><strong>Save/attach</strong> — gắn kết quả vào Task (liên kết G5) hoặc lưu vào Material Repository (liên kết G2), hoặc Export file về máy (FR 3.7.8).</li><li><strong>Credit History</strong> — danh sách job (video: <code>GET /videos</code>; caption: chưa có endpoint list sẵn, xem mục 8) + hiển thị trạng thái refunded.</li></ol><h2 id="_5-state-cache-tanstack-query" tabindex="-1">5. State &amp; cache (TanStack Query) <a class="header-anchor" href="#_5-state-cache-tanstack-query" aria-label="Permalink to &quot;5. State &amp; cache (TanStack Query)&quot;">​</a></h2><ul><li><code>useQuery([&#39;ai&#39;,&#39;credits&#39;, workspaceId])</code> — gọi <code>GET /credits</code>; <code>invalidateQueries([&#39;ai&#39;,&#39;credits&#39;, workspaceId])</code> ngay sau mọi <code>POST /videos</code> và <code>POST /captions</code> thành công (kể cả khi job video còn PENDING — credit đã bị trừ ngay lúc tạo job, không chờ job xong).</li><li><code>useQuery([&#39;ai&#39;,&#39;video-job&#39;, jobId], { refetchInterval: (data) =&gt; isOpen(data.status) ? 4000 : false })</code> — pattern chuẩn TanStack Query polling: dừng tự động khi status không còn PENDING/PROCESSING (tức <code>refetchInterval</code> trả <code>false</code>).</li><li>Khi job video chuyển <code>COMPLETED</code>/<code>FAILED</code>, invalidate lại <code>[&#39;ai&#39;,&#39;credits&#39;, workspaceId]</code> một lần nữa để phản ánh refund nếu có (trường hợp FAILED).</li><li>Caption/Image là mutation đơn (<code>useMutation</code>), không cần polling; sau khi thành công thì invalidate credit balance.</li><li>Danh sách job video (<code>[&#39;ai&#39;,&#39;videos&#39;, workspaceId]</code>) có thể để <code>staleTime</code> ngắn, refetch khi quay lại AI Hub/History screen.</li></ul><h2 id="_6-business-rules-đac-biet" tabindex="-1">6. Business rules đặc biệt <a class="header-anchor" href="#_6-business-rules-đac-biet" aria-label="Permalink to &quot;6. Business rules đặc biệt&quot;">​</a></h2><ul><li><strong>Charge trước khi generate, không phải sau khi xong</strong>: với video, <code>credits.charge()</code> chạy ngay sau khi AI service nhận job thành công (có <code>jobId</code>), trước khi job thực sự chạy xong — UI phải nói rõ &quot;đã trừ N credit, đang xử lý&quot; ngay từ bước Generating, không để user hiểu lầm là chỉ trừ khi có kết quả.</li><li><strong>Refund đúng 1 lần, idempotent</strong>: <code>AiVideoService.fail()</code> dùng status guard (<code>where status in (&#39;PENDING&#39;,&#39;PROCESSING&#39;)</code>) nên chỉ refund 1 lần dù gọi nhiều lần — mobile không cần tự chặn double-refund, nhưng không nên tự ý gọi lại generate khi job đang FAILED mà chưa kiểm tra <code>refunded</code> flag để tránh user hiểu lầm đã mất credit.</li><li><strong>Sweep job server-side mỗi 60s</strong> (<code>@Scheduled(fixedDelayString = &quot;${ai.video.sweep-delay-ms:60000}&quot;)</code>) tự fail + refund job treo quá <code>timeoutSeconds</code> (mặc định 600s, cấu hình <code>ai.video.timeout-seconds</code>) — mobile không cần timeout logic riêng, cứ tiếp tục poll hoặc hỏi lại <code>GET /videos/{jobId}</code> sau khi mở lại app.</li><li><strong>Insufficient credit</strong> → lỗi <code>INSUFFICIENT_AI_CREDIT</code> (HTTP 402 theo <code>BusinessException</code>/<code>ErrorCode</code>) ném ra TRƯỚC khi gọi AI service (<code>ensureAvailable</code>) — mobile cần bắt lỗi này riêng, hiện thông báo rõ &quot;không đủ credit&quot; + link tới màn hình Subscription/Billing (G7) thay vì lỗi chung.</li><li><strong>Creator limit</strong>: nếu Owner đặt <code>ai_credit_creator_limits</code> cho user, <code>remaining()</code> bị cap theo limit riêng của Creator đó dù agency còn credit — hiển thị rõ 2 số nếu cần debug (agency remaining vs creator remaining) nhưng UI chính chỉ cần hiện số <code>remaining</code> cuối cùng.</li><li><strong>Lỗi AI service 4xx (style/ambassador không hợp lệ) vs lỗi hạ tầng</strong>: <code>AiVideoService.generate()</code> phân biệt 400/422 → <code>INVALID_REQUEST</code> (style/ambassador sai) và các lỗi khác → <code>AI_SERVICE_UNAVAILABLE</code>; cả 2 trường hợp đều KHÔNG trừ credit (fail trước khi <code>credits.charge()</code> chạy) — khác hẳn trường hợp job fail sau khi đã charge (có refund). Mobile nên phân biệt 2 loại lỗi này trong UI copy.</li><li><strong>Image generation không có AiCreditService guard ở Java</strong> (xem mục 3.3) — business rule thật của luồng Image khác cơ bản so với Video/Caption, cần xác nhận lại trước khi code.</li></ul><h2 id="_7-viec-khong-lam-o-g6" tabindex="-1">7. Việc KHÔNG làm ở G6 <a class="header-anchor" href="#_7-viec-khong-lam-o-g6" aria-label="Permalink to &quot;7. Việc KHÔNG làm ở G6&quot;">​</a></h2><ul><li>Không làm &quot;edit video/raw footage có sẵn&quot; — đó là Creator Upload Giai đoạn 2 (G8, out of scope, chưa thiết kế, phụ thuộc năng lực AI edit thật chưa tồn tại trong <code>brandhub-ai-service</code>) theo đúng mục 2 và bảng giai đoạn trong <a href="./../mobile-app-plan.html">mobile-app-plan.md</a>.</li><li>Không làm màn hình quản lý Admin-level AI style/template (thêm/sửa/xoá style video/image) — đó thuộc FR 3.7.9 (Crawl Schedule) và các màn hình Admin khác, không nằm trong 3.7.4/3.7.6 (chỉ View template).</li><li>Không làm Trending Topics dashboard đầy đủ (3.7.1/3.7.10), Livestream Script (3.7.11), Recommend Collaborator (3.7.12) — các FR AI khác không liên quan trực tiếp tới generate caption/image/video + credit.</li><li>Không tự implement progress % thật cho video/image generation — chỉ phản ánh đúng trạng thái PENDING/PROCESSING/COMPLETED/FAILED mà server trả, không giả lập % tiến trình không có thật.</li></ul><h2 id="_8-rui-ro-cau-hoi-mo" tabindex="-1">8. Rủi ro/câu hỏi mở <a class="header-anchor" href="#_8-rui-ro-cau-hoi-mo" aria-label="Permalink to &quot;8. Rủi ro/câu hỏi mở&quot;">​</a></h2><ol><li><strong>Push notification khi job video xong</strong>: hiện server không có cơ chế push (FCM/APNs/Expo push token) gắn vào <code>AiVideoService</code> — cần thêm nếu muốn user không phải giữ app mở để chờ polling. Việc này đòi hỏi: (a) business-service lưu Expo push token theo user, (b) gọi Expo Push API khi job chuyển COMPLETED/FAILED trong <code>refresh()</code>/sweep. Chưa có trong code hiện tại — cần task riêng ở business-service trước khi mobile tận dụng được, nếu không mobile chỉ polling khi app foreground (khớp với quyết định &quot;không background task&quot; đã chốt ở <code>mobile-app-plan.md</code> §1).</li><li><strong>Download/preview video lớn trên mobile data</strong>: video Veo có thể vài chục MB, cảnh báo người dùng dùng Wifi khi preview/download, và nên dùng signed URL stream trực tiếp (không proxy qua app) để tránh tốn băng thông app.</li><li><strong>Credit flow của Image generation chưa rõ</strong> (mục 3.3, 6) — cần xác nhận với BE: ai-service Python có tự trừ credit riêng không, hay đây là gap thật cần vá trước khi mobile/web dựa vào. Nếu là gap, mobile không nên tự hiện &quot;đã trừ N credit&quot; cho Image vì sẽ sai so với thực tế backend.</li><li><strong>Image generation không có job/status polling</strong> — nếu thời gian xử lý thật dài (gần bằng video), cần bàn với BE việc đổi <code>/image/commercial/generate</code> sang pattern async/job giống video trước khi mobile cam kết UX đồng bộ (gọi 1 lần, chờ response).</li><li><strong>Danh sách lịch sử Caption generation</strong>: <code>AiCaptionService</code> lưu <code>ai_caption_generations</code> nhưng chưa thấy endpoint <code>GET</code> list theo workspace (chỉ có <code>/trend-fit</code>, generate/refine/adapt/choice) — cần thêm endpoint <code>GET /captions</code> (tương tự <code>GET /videos</code>) ở business-service nếu muốn màn hình Credit/Job History hiển thị đầy đủ cả 2 loại.</li></ol>',33)])])}const p=i(a,[["render",n]]);export{u as __pageData,p as default};
